import React, { useEffect, useState } from "react";
import "./index.scss";

// IDs of your sections in order
const SECTION_IDS = ["about", "portfolio", "contact"];
const NAV_OFFSET = 80; // height of your fixed nav, adjust if needed

const ScrollArrow = () => {
  const [isUp, setIsUp] = useState(false);

  // Helper: get an ordered list of sections that actually exist on the page
  const getSections = () => {
    return SECTION_IDS.map((id) => {
      const el = document.getElementById(id);
      if (!el) return null;
      const rect = el.getBoundingClientRect();
      return {
        id,
        el,
        top: rect.top + window.scrollY,
      };
    }).filter(Boolean);
  };

  // Update arrow direction based on scroll position
  useEffect(() => {
    const handleScroll = () => {
      const sections = getSections();
      if (!sections.length) return;

      const scrollY = window.scrollY || window.pageYOffset;

      // Find the last section whose top is above the current scroll
      let currentIndex = 0;
      for (let i = 0; i < sections.length; i += 1) {
        if (scrollY + NAV_OFFSET >= sections[i].top) {
          currentIndex = i;
        }
      }

      // If we're at/beyond last section, arrow should point UP
      setIsUp(currentIndex >= sections.length - 1);
    };

    handleScroll(); // run once on mount
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const handleClick = () => {
    const sections = getSections();
    if (!sections.length) return;

    const scrollY = window.scrollY || window.pageYOffset;

    // If arrow is UP → go to top
    if (isUp) {
      window.scrollTo({
        top: 0,
        behavior: "smooth",
      });
      return;
    }

    // Otherwise arrow is DOWN → go to the *next* section
    let nextSection = null;
    for (let i = 0; i < sections.length; i += 1) {
      if (sections[i].top - NAV_OFFSET > scrollY + 10) {
        nextSection = sections[i];
        break;
      }
    }

    // Fallback: if we don't find a "next" (edge case), go to last section
    if (!nextSection) {
      nextSection = sections[sections.length - 1];
    }

    const targetY = nextSection.top - NAV_OFFSET;

    window.scrollTo({
      top: targetY,
      behavior: "smooth",
    });
  };

  return (
    <button
      type="button"
      className={`scroll-arrow ${isUp ? "scroll-arrow--up" : "scroll-arrow--down"}`}
      onClick={handleClick}
      aria-label={isUp ? "Scroll to top" : "Scroll to next section"}
    >
      {/* Keep this empty span so your existing CSS can draw the arrow */}
      <span />
    </button>
  );
};

export default ScrollArrow;
